INSERT INTO "Question" ("id","prompt","options","correctIndex","explanation","difficulty","answers","hint","order","courseId","levelId","createdAt") VALUES
('q_fyz-sila-pohyb_0','V jaké jednotce se měří síla?',ARRAY['newton','watt','joule','pascal']::TEXT[],0,'Síla se měří v newtonech (N).',1,ARRAY[]::TEXT[],NULL,0,'c_fyz-sila-pohyb',NULL,NOW()),
('q_fyz-sila-pohyb_1','Jak se ve fyzice značí sílu?',ARRAY['m','S','v','F']::TEXT[],3,'Síla má značku F (anglicky force).',1,ARRAY[]::TEXT[],NULL,1,'c_fyz-sila-pohyb',NULL,NOW()),
('q_fyz-sila-pohyb_2','Čím se měří síla?',ARRAY['ampérmetrem','tlakoměrem','hodinami','siloměrem']::TEXT[],3,'Sílu měříme siloměrem s pružinou.',1,ARRAY[]::TEXT[],NULL,2,'c_fyz-sila-pohyb',NULL,NOW()),
('q_fyz-sila-pohyb_3','Která síla působí na všechna tělesa u Země směrem dolů?',ARRAY['magnetická síla','tíhová síla','třecí síla','odstředivá síla']::TEXT[],1,'Tíhová síla táhne tělesa směrem k Zemi.',1,ARRAY[]::TEXT[],NULL,3,'c_fyz-sila-pohyb',NULL,NOW()),
('q_fyz-sila-pohyb_4','V jaké jednotce se v soustavě SI měří hmotnost?',ARRAY['kilogram','newton','litr','metr']::TEXT[],0,'Hmotnost se měří v kilogramech (kg).',1,ARRAY[]::TEXT[],NULL,4,'c_fyz-sila-pohyb',NULL,NOW()),
('q_fyz-sila-pohyb_5','Jaká je přibližně rychlost chůze dospělého člověka?',ARRAY['50 km/h','5 km/h','0,5 km/h','500 km/h']::TEXT[],1,'Člověk jde zhruba 5 kilometrů za hodinu.',1,ARRAY[]::TEXT[],NULL,5,'c_fyz-sila-pohyb',NULL,NOW()),
('q_fyz-sila-pohyb_6','Auto ujede 120 km za 2 hodiny. Jaká je jeho průměrná rychlost?',ARRAY['240 km/h','30 km/h','122 km/h','60 km/h']::TEXT[],3,'v = s : t = 120 : 2 = 60 km/h.',2,ARRAY[]::TEXT[],NULL,6,'c_fyz-sila-pohyb',NULL,NOW()),
('q_fyz-sila-pohyb_7','Jak vypočítáme dráhu při stálé rychlosti?',ARRAY['s = v · t','s = v + t','s = t : v','s = v : t']::TEXT[],0,'Dráha je součin rychlosti a času.',2,ARRAY[]::TEXT[],NULL,7,'c_fyz-sila-pohyb',NULL,NOW()),
('q_fyz-sila-pohyb_8','Kolik km/h je 10 m/s?',ARRAY['10 km/h','3,6 km/h','36 km/h','100 km/h']::TEXT[],2,'Převod: m/s krát 3,6 dává km/h, tedy 10 · 3,6 = 36.',2,ARRAY[]::TEXT[],NULL,8,'c_fyz-sila-pohyb',NULL,NOW()),
('q_fyz-sila-pohyb_9','Která síla brzdí pohyb tělesa po podložce?',ARRAY['vztlaková síla','magnetická síla','tíhová síla','třecí síla']::TEXT[],3,'Tření působí proti pohybu tělesa po povrchu.',2,ARRAY[]::TEXT[],NULL,9,'c_fyz-sila-pohyb',NULL,NOW()),
('q_fyz-sila-pohyb_10','Cyklista jede stálou rychlostí 15 km/h. Kolik kilometrů ujede za 3 hodiny?',ARRAY['45 km','12 km','18 km','5 km']::TEXT[],0,'s = v · t = 15 · 3 = 45 km.',2,ARRAY[]::TEXT[],NULL,10,'c_fyz-sila-pohyb',NULL,NOW()),
('q_fyz-sila-pohyb_11','Jak velká je přibližně tíha tělesa o hmotnosti 1 kg (g ≈ 10 N/kg)?',ARRAY['asi 10 N','asi 100 N','asi 0,1 N','asi 1 N']::TEXT[],0,'F = m · g = 1 · 10 = 10 N.',2,ARRAY[]::TEXT[],NULL,11,'c_fyz-sila-pohyb',NULL,NOW()),
('q_fyz-sila-pohyb_12','Který Newtonův zákon říká, že těleso zůstává v klidu nebo v rovnoměrném přímočarém pohybu, dokud na ně nepůsobí vnější síla?',ARRAY['zákon zachování energie','třetí (zákon akce a reakce)','první (zákon setrvačnosti)','druhý (zákon síly)']::TEXT[],2,'To je první Newtonův zákon neboli zákon setrvačnosti.',3,ARRAY[]::TEXT[],NULL,12,'c_fyz-sila-pohyb',NULL,NOW()),
('q_fyz-sila-pohyb_13','Jak zní třetí Newtonův zákon?',ARRAY['čím větší hmotnost, tím větší rychlost','síla je součin hmotnosti a rychlosti','akce a reakce jsou stejně velké a opačného směru','každé těleso se pohybuje rovnoměrně']::TEXT[],2,'Když těleso působí na druhé silou, druhé působí na první stejně velkou silou opačného směru.',3,ARRAY[]::TEXT[],NULL,13,'c_fyz-sila-pohyb',NULL,NOW()),
('q_fyz-sila-pohyb_14','Vlak jede rychlostí 72 km/h. Kolik je to v m/s?',ARRAY['72 m/s','259 m/s','20 m/s','7,2 m/s']::TEXT[],2,'72 : 3,6 = 20 m/s.',3,ARRAY[]::TEXT[],NULL,14,'c_fyz-sila-pohyb',NULL,NOW()),
('q_fyz-sila-pohyb_15','Jak se nazývá vlastnost těles zůstat v klidu nebo v pohybu, pokud nepůsobí vnější síla?',ARRAY['tíha','vztlak','setrvačnost','hustota']::TEXT[],2,'Je to setrvačnost, vlastnost všech těles.',3,ARRAY[]::TEXT[],NULL,15,'c_fyz-sila-pohyb',NULL,NOW()),
('q_fyz-sila-pohyb_16','Co se stane s třecí silou, když povrch namažeme olejem?',ARRAY['zvětší se','zmenší se','změní se na tíhovou sílu','zůstane stejná']::TEXT[],1,'Mazání tření zmenšuje.',3,ARRAY[]::TEXT[],NULL,16,'c_fyz-sila-pohyb',NULL,NOW()),
('q_fyz-sila-pohyb_17','V čem je rozdíl mezi hmotností a tíhou tělesa?',ARRAY['obojí se měří v kg','hmotnost se měří v N, tíha v kg','hmotnost se měří v kg, tíha v N','obojí se měří v N']::TEXT[],2,'Hmotnost je v kilogramech, tíha je síla, a ta se měří v newtonech.',3,ARRAY[]::TEXT[],NULL,17,'c_fyz-sila-pohyb',NULL,NOW()),
('q_fyz-sila-pohyb_18','Jak se nazývá pohyb, při kterém těleso urazí za stejné časy stejné dráhy?',ARRAY['nerovnoměrný pohyb','zrychlený pohyb','rovnoměrný pohyb','zpomalený pohyb']::TEXT[],2,'Stejné dráhy za stejné časy znamenají rovnoměrný pohyb.',3,ARRAY[]::TEXT[],NULL,18,'c_fyz-sila-pohyb',NULL,NOW()),
('q_fyz-sila-pohyb_19','Jak se jmenuje jednoduchý stroj tvořený tyčí otáčivou kolem pevné osy?',ARRAY['nakloněná rovina','páka','kladka','šroub']::TEXT[],1,'Takový stroj je páka.',3,ARRAY[]::TEXT[],NULL,19,'c_fyz-sila-pohyb',NULL,NOW()),
('q_fyz-sila-pohyb_20','Na těleso působí síla 30 N doprava a 20 N doleva. Jaká je výslednice sil?',ARRAY['10 N doprava','50 N doprava','600 N doprava','10 N doleva']::TEXT[],0,'Opačné síly se odečtou: 30 − 20 = 10 N ve směru větší síly.',4,ARRAY[]::TEXT[],NULL,20,'c_fyz-sila-pohyb',NULL,NOW()),
('q_fyz-sila-pohyb_21','Těleso o hmotnosti 2 kg zrychluje silou 10 N. Jaké je zrychlení?',ARRAY['5 m/s²','12 m/s²','0,2 m/s²','20 m/s²']::TEXT[],0,'a = F : m = 10 : 2 = 5 m/s².',4,ARRAY[]::TEXT[],NULL,21,'c_fyz-sila-pohyb',NULL,NOW()),
('q_fyz-sila-pohyb_22','Jakou dráhu ujede auto rychlostí 20 m/s za 30 s?',ARRAY['50 m','6 000 m','150 m','600 m']::TEXT[],3,'s = v · t = 20 · 30 = 600 m.',4,ARRAY[]::TEXT[],NULL,22,'c_fyz-sila-pohyb',NULL,NOW()),
('q_fyz-sila-pohyb_23','Za jak dlouho ujede cyklista rychlostí 20 km/h dráhu 50 km?',ARRAY['2,5 h','1 000 h','0,4 h','3 h']::TEXT[],0,'t = s : v = 50 : 20 = 2,5 h.',4,ARRAY[]::TEXT[],NULL,23,'c_fyz-sila-pohyb',NULL,NOW()),
('q_fyz-sila-pohyb_24','Jak se liší tíha stejného tělesa na Měsíci od tíhy na Zemi?',ARRAY['na Měsíci je asi šestinová','na Měsíci je nulová','na Měsíci je šestinásobná','je stejná']::TEXT[],0,'Tíhové zrychlení na Měsíci je asi šestina pozemského.',4,ARRAY[]::TEXT[],NULL,24,'c_fyz-sila-pohyb',NULL,NOW()),
('q_fyz-sila-pohyb_25','Jak se nazývá bod, v němž můžeme těleso podepřít tak, aby zůstalo v rovnováze?',ARRAY['vztažný bod','střed otáčení','těžiště','bod zlomu']::TEXT[],2,'Působiště tíhové síly je těžiště.',4,ARRAY[]::TEXT[],NULL,25,'c_fyz-sila-pohyb',NULL,NOW()),
('q_fyz-sila-pohyb_26','Která z těchto veličin je vektorová, tedy má i směr?',ARRAY['síla','hmotnost','teplota','čas']::TEXT[],0,'Síla má velikost i směr.',5,ARRAY[]::TEXT[],NULL,26,'c_fyz-sila-pohyb',NULL,NOW()),
('q_fyz-sila-pohyb_27','Auto zrychluje z klidu na 20 m/s za 5 s. Jaké je jeho zrychlení?',ARRAY['15 m/s²','0,25 m/s²','100 m/s²','4 m/s²']::TEXT[],3,'a = Δv : t = 20 : 5 = 4 m/s².',5,ARRAY[]::TEXT[],NULL,27,'c_fyz-sila-pohyb',NULL,NOW()),
('q_fyz-sila-pohyb_28','Proč se cestující v autě při prudkém brzdění zhoupne dopředu?',ARRAY['protože ho táhne motor','kvůli setrvačnosti těla','protože se zvětší jeho hmotnost','protože sedadlo klouže']::TEXT[],1,'Tělo má snahu pokračovat v původním pohybu.',5,ARRAY[]::TEXT[],NULL,28,'c_fyz-sila-pohyb',NULL,NOW()),
('q_fyz-sila-pohyb_29','Jak se změní třecí síla, když těleso o dvojnásobné hmotnosti táhneme po stejném povrchu?',ARRAY['zůstane stejná','zmenší se na polovinu','zvětší se na dvojnásobek','zvětší se čtyřnásobně']::TEXT[],2,'Třecí síla je přímo úměrná tlakové síle, tedy tíze tělesa.',5,ARRAY[]::TEXT[],NULL,29,'c_fyz-sila-pohyb',NULL,NOW()),
('q_fyz-sila-pohyb_30','Kdy je páka v rovnováze?',ARRAY['když jsou obě ramena stejně dlouhá','když jsou momenty sil na obou stranách stejné','když je delší rameno nahoře','když na ni působí jen jedna síla']::TEXT[],1,'Rovnováha nastane při stejném součinu síly a ramene na obou stranách.',5,ARRAY[]::TEXT[],NULL,30,'c_fyz-sila-pohyb',NULL,NOW()),
('q_fyz-elektrina_0','V jaké jednotce se měří elektrický proud?',ARRAY['watt','ohm','ampér','volt']::TEXT[],2,'Proud se měří v ampérech (A).',1,ARRAY[]::TEXT[],NULL,0,'c_fyz-elektrina',NULL,NOW()),
('q_fyz-elektrina_1','V jaké jednotce se měří elektrické napětí?',ARRAY['ohm','joule','ampér','volt']::TEXT[],3,'Napětí se měří ve voltech (V).',1,ARRAY[]::TEXT[],NULL,1,'c_fyz-elektrina',NULL,NOW()),
('q_fyz-elektrina_2','V jaké jednotce se měří elektrický odpor?',ARRAY['ampér','ohm','volt','watt']::TEXT[],1,'Odpor se měří v ohmech (Ω).',1,ARRAY[]::TEXT[],NULL,2,'c_fyz-elektrina',NULL,NOW()),
('q_fyz-elektrina_3','Který materiál je dobrým vodičem elektrického proudu?',ARRAY['guma','sklo','měď','plast']::TEXT[],2,'Kovy, například měď, vedou proud dobře.',1,ARRAY[]::TEXT[],NULL,3,'c_fyz-elektrina',NULL,NOW()),
('q_fyz-elektrina_4','Který materiál je elektrický izolant?',ARRAY['železo','guma','hliník','měď']::TEXT[],1,'Guma proud nevede.',1,ARRAY[]::TEXT[],NULL,4,'c_fyz-elektrina',NULL,NOW()),
('q_fyz-elektrina_5','Co je zdrojem elektrického napětí?',ARRAY['žárovka','vypínač','baterie','drát']::TEXT[],2,'Baterie je zdroj napětí.',1,ARRAY[]::TEXT[],NULL,5,'c_fyz-elektrina',NULL,NOW()),
('q_fyz-elektrina_6','Čím se měří elektrický proud?',ARRAY['ampérmetrem','teploměrem','voltmetrem','siloměrem']::TEXT[],0,'Proud měříme ampérmetrem.',2,ARRAY[]::TEXT[],NULL,6,'c_fyz-elektrina',NULL,NOW()),
('q_fyz-elektrina_7','Čím se měří elektrické napětí?',ARRAY['voltmetrem','ampérmetrem','tlakoměrem','siloměrem']::TEXT[],0,'Napětí měříme voltmetrem.',2,ARRAY[]::TEXT[],NULL,7,'c_fyz-elektrina',NULL,NOW()),
('q_fyz-elektrina_8','Jak se ve fyzice značí elektrické napětí?',ARRAY['R','U','P','I']::TEXT[],1,'Napětí má značku U.',2,ARRAY[]::TEXT[],NULL,8,'c_fyz-elektrina',NULL,NOW()),
('q_fyz-elektrina_9','Jak se ve fyzice značí elektrický proud?',ARRAY['I','U','W','R']::TEXT[],0,'Proud má značku I.',2,ARRAY[]::TEXT[],NULL,9,'c_fyz-elektrina',NULL,NOW()),
('q_fyz-elektrina_10','Jak zní Ohmův zákon pro proud?',ARRAY['I = U : R','I = U + R','I = R : U','I = U · R']::TEXT[],0,'Proud je napětí dělené odporem.',2,ARRAY[]::TEXT[],NULL,10,'c_fyz-elektrina',NULL,NOW()),
('q_fyz-elektrina_11','K čemu v obvodu slouží vypínač?',ARRAY['spojuje a přerušuje obvod','zvyšuje napětí','vyrábí elektřinu','měří proud']::TEXT[],0,'Vypínač obvod zavírá a otevírá.',2,ARRAY[]::TEXT[],NULL,11,'c_fyz-elektrina',NULL,NOW()),
('q_fyz-elektrina_12','Jaké střídavé napětí je v běžné zásuvce v České republice?',ARRAY['12 V','10 000 V','1,5 V','230 V']::TEXT[],3,'Zásuvkové napětí je 230 V.',2,ARRAY[]::TEXT[],NULL,12,'c_fyz-elektrina',NULL,NOW()),
('q_fyz-elektrina_13','Obvodem teče proud 2 A při napětí 12 V. Jak velký je odpor?',ARRAY['24 Ω','0,17 Ω','10 Ω','6 Ω']::TEXT[],3,'R = U : I = 12 : 2 = 6 Ω.',3,ARRAY[]::TEXT[],NULL,13,'c_fyz-elektrina',NULL,NOW()),
('q_fyz-elektrina_14','Spotřebič má odpor 10 Ω a je připojen na napětí 5 V. Jaký proud jím teče?',ARRAY['50 A','2 A','5 A','0,5 A']::TEXT[],3,'I = U : R = 5 : 10 = 0,5 A.',3,ARRAY[]::TEXT[],NULL,14,'c_fyz-elektrina',NULL,NOW()),
('q_fyz-elektrina_15','Jak jsou zapojeny žárovky, když se po vyšroubování jedné zhasnou všechny?',ARRAY['paralelně','každá má vlastní zdroj','sériově','smíšeně se zkratem']::TEXT[],2,'V sériovém zapojení přerušení na jednom místě přeruší celý obvod.',3,ARRAY[]::TEXT[],NULL,15,'c_fyz-elektrina',NULL,NOW()),
('q_fyz-elektrina_16','Jak jsou zapojeny spotřebiče v domácnosti?',ARRAY['bez uzavřeného obvodu','paralelně','sériově','jen smíšeně']::TEXT[],1,'Paralelní zapojení umožňuje, aby každý spotřebič fungoval samostatně.',3,ARRAY[]::TEXT[],NULL,16,'c_fyz-elektrina',NULL,NOW()),
('q_fyz-elektrina_17','Jak se nazývá stav, kdy se vodiče o malém odporu spojí a obvodem teče velký proud?',ARRAY['indukce','přepětí','zkrat','rezonance']::TEXT[],2,'Zkrat je nebezpečný, může způsobit požár.',3,ARRAY[]::TEXT[],NULL,17,'c_fyz-elektrina',NULL,NOW()),
('q_fyz-elektrina_18','Co musí platit, aby obvodem tekl proud?',ARRAY['musí být uzavřený a obsahovat zdroj','musí obsahovat jen izolanty','musí být rozpojený','musí mít aspoň tři žárovky']::TEXT[],0,'Potřebujeme zdroj a uzavřený vodivý okruh.',3,ARRAY[]::TEXT[],NULL,18,'c_fyz-elektrina',NULL,NOW()),
